import {thanksMarkup,feedbackMarkup,readFeedbackDraft,bindFeedback} from './community.js';
import {headingIcon} from './interface-icons.js';
import {rulesMarkup} from './rules-view.js';
import {initMusic,musicTrigger,syncMusicUI} from './bgm.js';
import {OUTCOME_NAMES} from './chronicle.js';
import {attributeGuide,attributeHint} from './creation-guide.js';
import {endingMarkup} from './ending-view.js';
import {FACTIONS,sourceFaction,unitFaction,nodeFactions,factionImage} from './factions.js';
import {wheelSpeed,wheelDuration,normalizeSpeed,reducedMotion} from './wheel-settings.js';
import {statTier,unitResources,artResourceRule,isLeader} from './unit-info.js';
import {narrative,mission} from './briefings.js';
import {DATA} from './data.js';
import {syncMotion,toggleMemes,leaderBusy} from './motion.js';
import {CARDS,BY_ID,STATUS_INFO,actionText,actionFor} from './cards.js';
import {TIERS,AXIS_NAMES,value,clamp,tierLabel,numericRating,initialHighChance,energyRegen,restEnergy,freshSeed} from './math.js';
import * as Run from './run.js';
import * as Battle from './battle.js';
import {sceneSummary} from './scenes.js';
import {wheelMarkup,creationOptions,dailyOptions,artsOptions,vectorTierOptions,selectedCreationId,bindWheels} from './wheel.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let state=null,view=location.hash==='#feedback'?'feedback':'home',spinning=false,selection='martial',target=null,auto=false,timer=null,search='',pool='all',pause=false;
let animation=null,finalReveal=false,detailUnit='player',beneficiary='',vectorPreview='tier';
let mobilePanel='skills',mobileSkill='A',auxOpen=false,branchChoice=null,feedbackReturn='home';
const thankedRuns=new Set();
const compactCombat=matchMedia('(max-width:760px), (max-width:1000px) and (max-height:500px)');
compactCombat.addEventListener('change',()=>{if(view==='play'&&state?.phase==='battle')render();});
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statTierMarkup=(stats,key)=>statTier(stats,key).split(' · ').map((text,i)=>`<span class="${i?'tier-description':'tier-code'}">${esc(text)}</span>`).join('');
const fmt=x=>Number.isFinite(x)?Math.floor(x).toLocaleString('zh-CN'):'—';
const btn=(label,action,cls='',disabled=false,extra='')=>`<button class="${cls}" data-act="${action}" ${disabled?'disabled':''} ${extra}>${label}</button>`;
const tag=(label,cls='')=>`<span class="tag ${cls}">${esc(label)}</span>`;
const bar=(v,max,cls='')=>`<div class="bar ${cls}"><i style="width:${clamp(v/Math.max(1,max)*100,0,100)}%"></i></div>`;
function persist(){if(state&&state.mode!=='sandbox')try{Run.save(state);}catch(e){toast('存档写入失败，请导出存档备份');}}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.style.display='block';clearTimeout(el._timer);el._timer=setTimeout(()=>el.style.display='none',3500);}
try{state=Run.load();}catch{toast('存档无法读取，可导入备份或新建角色');}
function header(){return `<div class="terminal-strip"><span><i></i> PRTS / 泰拉档案终端</span><div class="terminal-tools"><span>${view==='home'?'穿越者档案':'旅程档案'} · 自动保存</span>${musicTrigger()}</div></div><header class="topbar"><div class="brand"><img src="assets/prts/factions/rhodes.png" alt="罗德岛标志"><div><strong>泰拉 · 命运转盘</strong><span>PRTS / TERRA FIELD ARCHIVE</span></div></div><nav class="top-actions" aria-label="游戏导航">${btn('源石技艺','codex','ghost small')}${btn('旅程图','route','ghost small')}${btn('规则','help','ghost small')}${view==='home'?btn('意见反馈','feedback','ghost small'):''}${btn(localStorage.getItem('terra-ui-memes')==='off'?'彩蛋关':'彩蛋开','toggleMemes','ghost small')}${btn('模拟作战','simulation','ghost small')}${state?btn('存档','saveMenu','ghost small'):''}</nav></header>`;}
function render(){const savedScroll=[...app.querySelectorAll('.unit-list,.skills-pane,.skill-descriptions,.battle-file,.battle-log')].map(el=>({top:el.scrollTop,bottom:el.scrollHeight-el.clientHeight-el.scrollTop<24}));clearTimeout(timer);const enteringEnding=view==='play'&&state?.phase==='ending'&&document.body.dataset.view!=='ending';const combat=view==='play'&&state?.phase==='battle';document.body.dataset.view=view==='play'?((state?.pendingGrowth||state?.pendingTrainingGrowth)&&!spinning?'growth':state?.phase||'home'):view;document.body.classList.toggle('in-combat',combat);document.body.classList.toggle('in-roulette',view==='play'&&(!!animation||state?.phase==='creation'||state?.phase==='vectorPrep'||finalReveal));app.innerHTML=header()+`<main class="shell">${view==='home'?home():view==='codex'?codex():view==='route'?route():view==='feedback'?feedbackMarkup(readFeedbackDraft()):gameView()}</main>${combat?'':`<footer class="footer">明日方舟同人策略游戏 · 自动存档 · <a href="https://prts.wiki/w/首页" target="_blank" rel="noreferrer">PRTS 素材来源</a></footer>`}`;bind();app.querySelectorAll('.unit-list,.skills-pane,.skill-descriptions,.battle-file,.battle-log').forEach((el,i)=>{const saved=savedScroll[i];if(saved&&!(el.classList.contains('battle-log')&&saved.bottom))el.scrollTop=saved.top;});syncMusicUI();if(enteringEnding){const heading=app.querySelector('.chronicle-heading h1');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}if((state?.pendingGrowth||state?.pendingTrainingGrowth)&&!spinning&&view==='play')animateGrowth();syncMotion({combat,battle:state?.battle,phase:document.body.dataset.view,growth:state?.pendingGrowth||(!spinning&&state?.pendingTrainingGrowth),ending:state?.ending});if(combat)schedule();if(enteringEnding&&!thankedRuns.has(state.id)){const endingId=state.id;requestAnimationFrame(()=>{if(view==='play'&&state?.phase==='ending'&&state.id===endingId&&!modal.open){thankedRuns.add(endingId);openModal('旅程之后 · 致谢',thanksMarkup());}});}}
function home(){return `<section class="hero-start"><div class="start-title"><div class="home-insignia">${factionImage(FACTIONS.rhodes)}<span>RHODES ISLAND<br>PERSONNEL TERMINAL</span></div><h1>泰拉<br>命运转盘</h1><div class="start-line"></div><p>从一名来到泰拉的穿越者开始。抽取你的出身与源石技艺，转动每日成长转盘，在泰拉的关键时刻做出自己的选择。</p><div class="statsline"><div><strong>${CARDS.length}</strong><span>源石技艺</span></div><div><strong>12</strong><span>穿越节点</span></div><div><strong>48</strong><span>剧情作战</span></div></div>${state?`<div class="notice">已有档案：${esc(state.name==='博士'?'穿越者':state.name)} · ${state.phase==='creation'?'建角 '+state.step+'/11':esc(Run.nodeOf(state)?.name||'旅程结束')}</div>${btn('继续旅程','continue','primary')}`:''}</div><section class="panel"><div class="eyebrow">NEW CHRONICLE</div><h2>创建穿越者档案</h2><div class="formgrid"><label>你的名字<input id="name" maxlength="20" value="穿越者" autocomplete="off"></label><label>旅程模式<select id="mode"><option value="campaign">连贯战役 · 向终局推进</option><option value="single">独立节点 · 完成四场作战</option></select></label><label>穿越起点<select id="start-node"><option value="random">命运转盘决定</option>${DATA.campaign.nodes.map(n=>`<option value="${n.id}">${n.id} ${n.name}</option>`).join('')}</select></label><label class="checklabel wide"><input id="iron" type="checkbox">铁人模式：自身阵亡即结束本局</label><label class="checklabel wide"><input id="legend" type="checkbox">传奇之路：隐藏源石技艺概率提高至30%</label><label class="checklabel wide"><input id="solo" type="checkbox">一人成军：不编入剧情队友，高阶初始战力概率提升</label><label class="checklabel wide"><input id="hazard" type="checkbox">险路恶敌：更强的敌人，更高的初始战力与成长</label><p class="mode-explain wide">险路恶敌：敌方生命+50%，双攻击+30%，双抗与技力+20%；五项属性成长+50%，熟练度不变。每项初始B−及以上45.4%，叠加一人成军79.4%。</p><p class="mode-explain wide">仅开启一人成军时，每项初始战力抽到B−及以上的概率为66.5%；源石技艺召唤物与任务设施仍可使用。</p></div><details class="advanced-settings"><summary>高级设置 · 命运种子</summary><label>命运种子<input id="seed" placeholder="留空随机生成" maxlength="40" autocomplete="off"></label></details><p class="smalltext muted">出生地与种族仅提供背景。高低战力独立抽取，熟练度解锁招式，成长天赋决定修行效率。</p><div class="divider"></div>${btn(state?'新建另一段旅程':'开始命运转盘','new','primary')} ${btn('导入存档','import','ghost small')} ${btn('意见反馈','feedback','ghost small')}<p class="smalltext muted" style="margin-top:12px">剧情作战未达成目标即结束本局，所有模式均适用。建议首次选择切城营救。</p></section></section><section class="startfoot"><article><div class="eyebrow">01 / ORIGIN</div><strong>抽取起点，选择方向</strong><p>九档成长资质，普通与隐藏源石技艺池。低起点也能通过修行寻找自己的打法。</p></article><article><div class="eyebrow">02 / PREPARATION</div><strong>每一天都有取舍</strong><p>随机锻炼、磨练源石技艺，或在矢量突破中检验自己。剧情不会无限等待。</p></article><article><div class="eyebrow">03 / DECISION</div><strong>读懂下一次攻击</strong><p>观察敌方意图与行动轴，用控制、防御和召唤完成任务。生存也可以是胜利。</p></article></section>`;}
function pagehead(kicker,title,desc,actions=''){return `<div class="pagehead"><div class="field-heading">${headingIcon(kicker,title)}<div><div class="eyebrow">${kicker}</div><h1>${esc(title)}</h1>${desc?`<p class="muted">${desc}</p>`:''}</div></div><div class="row">${actions}</div></div>`;}
function side(){if(!state?.stats||animation?.type==='creation')return `<aside class="panel sidepanel"><h3>人物档案</h3><p class="muted smalltext">命运会在每次转动后留下记录。</p><ul class="archive-list">${state.rolls.filter(r=>!spinning||animation?.type!=='creation'||r.step!==animation.step).map((r,i)=>`<li><span>${Run.STEPS[i]}</span><strong>${esc(rollLabel(r))}</strong></li>`).join('')}</ul></aside>`;
 const c=BY_ID[state.art];return `<aside class="panel sidepanel"><div class="dossier-insignia">${factionImage(FACTIONS.rhodes)}<span>PERSONNEL FILE<br>罗德岛 / 博士档案</span></div><h2>${esc(state.name)}</h2><div class="row" style="margin:10px 0">${tag(state.identity==='I01'?'感染者':'非感染者')}${tag('成长天赋 '+state.talent+' · ×'+state.multiplier,'gold')}${state.solo?tag('一人成军'):''}${state.hazard?tag('险路恶敌','gold'):''}</div><p class="smalltext muted">${esc(state.rolls[0]?.name)} / ${esc(state.rolls[1]?.name)}</p><div class="divider"></div><h3 class="gold">${esc(tierLabel(numericRating(state.stats).score))}</h3><p class="tiny muted">以下为基础指标；身份修正计入实战面板和综合评级。</p>${state.axes.map((a,i)=>`<div class="statblock"><div class="row smalltext"><span class="muted">${AXIS_NAMES[i]}</span><span>${value(a.score).toFixed(1)}</span></div>${bar(a.score%1,1)}<small class="muted">${tierLabel(a.score)}${a.reserve>0?' · 待突破 '+a.proof:''}</small></div>`).join('')}<div class="divider"></div><div class="archive-combat-values">${STAT_FIELDS.map(([k,l])=>`<span><span class="stat-label">${l}</span><b>${precise(state.stats[k])}</b><small class="stat-tier">${statTierMarkup(state.stats,k)}</small></span>`).join('')}</div><div class="divider"></div><h3>${esc(c.name)} ${hiddenMark(c)}</h3>${resourceRuleUI(c,state.mastery)}<p class="smalltext muted">${esc(c.source)}${state.mastery>=200&&c.ascend?' / '+esc(c.ascend):''}</p><div class="row smalltext" style="justify-content:space-between;margin-top:12px"><span>熟练度</span><span>${state.mastery} / 200</span></div>${bar(state.mastery,200,'gold')}<p class="smalltext muted" style="margin-top:10px">100 专精 · 200 升变 · 不受天赋影响</p>${btn('查看源石技艺','card:'+c.id,'ghost small')}</aside>`;}
function gameView(){if(!state)return home();if(state.pendingGrowth&&!spinning)return growthScreen();if(state.pendingTrainingGrowth&&!spinning)return trainingGrowthScreen();if(finalReveal||animation?.type==='creation')return creation();if(animation?.type==='daily')return camp();switch(state.phase){case'creation':return creation();case'confirm':return confirm();case'camp':return camp();case'vectorPrep':return vectorPrep();case'prep':return prep();case'battle':return battleView();case'result':return result();case'nodeEnd':return nodeEnd();case'ending':return ending();default:return home();}}
function rollLabel(r){if(r.score!==undefined)return tierLabel(r.score);if(r.grade)return r.grade+' · '+r.name+' · ×'+r.multiplier;return r.name+((r.pool||BY_ID[r.id]?.pool)==='hidden'?'〔隐藏〕':'');}
function hiddenMark(c){return c?.pool==='hidden'?tag('隐藏','hidden-art'):'';}
function battleBranches(b,p){const c=Battle.cardOf(p);if(!c?.modes)return '';if(c.id==='AK035')return `<div class="battle-branch fixed-branch"><span>本场仆役</span><strong>${esc(c.modes[p.mode])}</strong><small>战前配置</small></div>`;const mode=branchChoice?.battle===b&&branchChoice.unit===p.id?branchChoice.mode:p.mode;return `<div class="battle-branch"><label for="action-mode">技能分支</label><select id="action-mode" aria-label="技能分支">${c.modes.map((m,i)=>`<option value="${i}" ${mode===i?'selected':''}>${esc(m)}</option>`).join('')}</select><small>随下一次行动生效</small></div>`;}
const motionReduced=reducedMotion;
const spinDuration=()=>animation?.duration??wheelDuration(wheelSpeed(),motionReduced());
function wheel(result,options,title,selected){return wheelMarkup({result,options,title,selected,rolling:spinning,duration:spinDuration()});}
function creation(){const done=state.step>=11,i=animation?.type==='creation'?animation.step:done?10:Math.max(0,state.step-1),row=state.rolls.find(r=>r.step===i);
 return pagehead('档案生成 / '+String(i+1).padStart(2,'0')+' OF 11',Run.STEPS[i],'抽取你的起点，每一步都会自动记录。')+`<div class="layout"><section class="panel"><div class="origin-stage"><strong>${String(i+1).padStart(2,'0')} / 11</strong><div class="progress-steps">${Run.STEPS.map((_,j)=>`<span class="${j<state.step?'done':''}"></span>`).join('')}</div></div>${attributeGuide(i,state,spinning?null:row)}<div class="wheel-area">${wheel(row?rollLabel(row):'',creationOptions(i,state),Run.STEPS[i],selectedCreationId(row))}</div><div class="wheel-caption"><p>${rollHint(i)}</p>${!spinning&&!done&&state.step!==i&&attributeHint(state.step)?`<span class="next-wheel-purpose">即将抽取：${esc(attributeHint(state.step))}</span>`:''}${done?btn(spinning?'正在揭晓天赋…':'查看完整档案','revealArchive','primary',spinning):btn(spinning?'正在揭晓…':'转动 · '+Run.STEPS[state.step],'roll','primary',spinning)}${!spinning&&!done&&row?`<p class="next-wheel">下一轮：${Run.STEPS[state.step]}</p>`:''}</div></section>${side()}</div>`;}

function rollHint(i){if(i<2)return '只决定你的故事背景，不改变战力与成长。';if(i===2)return '感染者：生命上限−10%，源石技艺强度+15%；非感染者：生命上限+10%。';if(i===3)return '起点决定准备时间与剧情。每场作战会告知当前任务。';if(i===4)return (state.legend?'传奇之路：普通池70%，隐藏池30%。':'普通池95%，隐藏池5%。')+'所有源石技艺从熟练度0开始。';if(i===10)return '成长资质只影响五项指标的锻炼增幅，不影响熟练度与升变。九档训练倍率：0.50—2.10。';return ((state.solo||state.hazard)?`${state.hazard?'险路恶敌':''}${state.hazard&&state.solo?'＋':''}${state.solo?'一人成军':''}：B−及以上${(initialHighChance(state.solo,state.hazard)*100).toFixed(1)}%。`:'')+'从战场中坚至崛起之物独立抽取。大国将军以上概率随强度递减。';}
function skillPanels(c,mastery=state?.mastery||0,onlyAB=false){return resourceRuleUI(c,mastery)+`<div class="skill-grid">${c.actions.filter((_,i)=>!onlyAB||i<2).map((_,i)=>{let a=actionFor(c,i,mastery);return `<article class="skill ${mastery<a.unlock?'locked':''}"><div class="row">${tag(a.button)}${a.button==='C'?tag('M200 · 升变','gold'):''}</div><h3 style="margin-top:12px">${esc(a.name)}</h3>${a.label!==a.name?`<small class="muted">${esc(a.label)}</small>`:''}<div class="skill-meta">${Math.ceil(a.cost*.9)} E · 冷却${a.cd}回合 · ${targetLabel(a.target)}${a.fromRound?' · 第'+a.fromRound+'战场轮起':''}${a.limit?' · 本场限'+a.limit+'次':''}</div><p>${esc(chineseText(actionText(a)))}</p></article>`;}).join('')}</div>`;}
function targetLabel(t){return {self:'自身',enemy_one:'敌单体',enemy_all:'敌全体',enemy_two:'敌方双目标',enemy_three:'敌方三目标',enemy_up_to_two:'至多2敌',enemy_up_to_three:'至多3敌',ally_one:'友单体',ally_main_one:'友方主体',ally_healable_one:'可治疗友方',ally_all:'友全体',ally_all_mains:'友方全体主体',recorded_targets:'记录目标',choose_mode:'选择技能分支'}[t]||t;}
function confirm(){let c=BY_ID[state.art];return pagehead('FILE / COMPLETE','你的旅程，已经有了起点',`${esc(state.rolls[3].name)} · ${state.mode==='campaign'?'连贯战役':'独立节点'}`,btn('确认档案 · 进入泰拉','confirm','primary'))+`<div class="layout"><div><section class="panel"><div class="sectiontitle"><h2>${esc(c.name)}</h2>${tag(c.pool==='hidden'?'隐藏源石技艺':'普通源石技艺',c.pool==='hidden'?'gold':'')}</div><p class="muted">${esc(c.source)}的能力原型 · ${esc(c.tip||'从基础招式开始，寻找属于自己的作战节奏。')}</p><div class="divider"></div>${skillPanels(c,0)}</section><div class="notice">初始生命 ${fmt(state.stats.H)} · 体术 ${fmt(state.stats.A)} · 源石技艺强度 ${fmt(state.stats.P)} · 技力 ${state.stats.Emax}。<br>成长天赋 ${esc(state.talent)}，后续训练倍率 ×${state.multiplier}${state.hazard?' ×1.5（险路恶敌）':''}；不额外增加开局属性。</div></div>${side()}</div>`;}
function masteryConfig(){return `<div class="auto-progression"><div class="${state.mastery>=100?'unlocked':''}"><b>M100 · 专精${state.mastery>=100?'已自动应用':''}</b><span>A/B伤害系数 +15%，各减少3基础技力消耗。</span></div><div class="${state.mastery>=200?'unlocked':''}"><b>M200 · 升变${state.mastery>=200?'已自动应用':''}</b><span>A/B伤害系数再 +20%、各再减2基础技力；C解锁、系数 +20%、减4基础技力。保留原招式，叠加异格收益。</span></div></div>${BY_ID[state.art].modes?`<label for="summon-mode">${BY_ID[state.art].id==='AK035'?'本场仆役类型':'初始技能分支'}<select id="summon-mode">${BY_ID[state.art].modes.map((m,i)=>`<option value="${i}" ${state.summonMode===i?'selected':''}>${m}</option>`).join('')}</select></label>`:''}`;}
function chineseText(text){return String(text).replace(/([0-9.%＋+−×()（）/]+)Q/g,'$1较高攻击强度').replace(/([0-9.%＋+−×()（）/]+)H/g,'$1最大生命').replace(/([0-9.%＋+−×()（）/]+)A/g,'$1体术强度').replace(/([0-9.%＋+−×()（）/]+)P/g,'$1源石技艺强度').replace(/([0-9.%＋+−×()（）/]+)D/g,'$1防御').replace(/([0-9.%＋+−×()（）/]+)R/g,'$1魔抗').replace(/A\/P/g,'体术/源石技艺强度').replace(/HP/g,'生命');}
function growthJournal(){return `<section class="panel"><h3>作战成长记录</h3><div class="journal">${state.history.slice(-48).reverse().map(r=>`<div><strong>${esc(r.title)} · ${r.won?'完成':'撤离'}</strong><p class="smalltext">${growthText({...r,mastery:0})||'未获得指标成长'}${r.mastery?'；熟练度 +'+r.mastery:''}</p></div>`).join('')||'<p class="muted">完成剧情作战后在此记录成长。</p>'}</div></section>`;}
function growthText(r){return (r.gains||r.growth||[]).map(g=>`${AXIS_NAMES[g.axis]}：基础${g.base.toFixed(2)} × 天赋${fmt(g.talentMult??g.mult)}${g.modeMult>1?' × 险路恶敌'+fmt(g.modeMult):''}${g.factor!==1?' × 高阶效率'+g.factor:''} → ${(g.values||[]).map(v=>({H:'最大生命',D:'防御',A:'体术强度',P:'源石技艺强度',R:'魔抗',Emax:'技力上限'}[v.key]+' +'+precise(v.gain))).join('、')}`).join('<br>')+(r.mastery?`<br>熟练度：${r.masteryBase||r.mastery} × ${r.masteryMultiplier??1} → +${r.mastery}（上限200）`:'');}
function camp(){let n=Run.nodeOf(state),r=state.lastDaily;return pagehead('CAMP / '+n.id,'出发之前',`${esc(n.name)} · 剩余 <strong class="gold">${state.days}</strong> 个准备日`,btn(state.days?'提前出发':'进入作战','depart','primary',spinning))+`<div class="layout"><div><section class="panel"><div class="sectiontitle"><h3>今日成长转盘</h3>${tag('补给 '+state.supply)}</div><div class="daily-wheel">${wheel(r?.name?.split(' · ')[0],dailyOptions(),'今日行程',Run.DAILY_PROJECTS.find(p=>r?.name?.startsWith(p.name))?.name)}</div><div class="wheel-caption">${btn(spinning?'正在揭晓…':'转动 · 今日行程','daily','primary',spinning||state.days<=0)}</div><p class="smalltext muted">转盘选择锻炼项目；矢量突破抽取岛上干员源石技艺与对手评级。每日结束生命回满；矢量突破在战斗结算后回满。</p></section><section class="panel"><h3>战前招式配置</h3>${masteryConfig()}</section>${growthJournal()}<section class="panel"><h3>日常成长记录</h3><div class="journal">${state.dailyHistory.slice(-12).reverse().map(r=>`<div><strong>第${r.day}日 · ${esc(r.name)}${r.type==='vector'?' · '+(r.won?'突破成功':'未通过'):''}</strong><p class="smalltext muted">${r.type==='vector'&&r.reason?esc(r.reason)+' · ':''}${growthText(r)|| (r.supply?'补给 +'+r.supply:r.type==='vector'?'未取得成长，返回日程':'恢复生命')}</p></div>`).join('')||'<p class="muted">命运将记录每一次成长。</p>'}</div></section></div>${side()}</div>`;}
function vectorPrep(){const r=state.pendingTraining;return pagehead('PRTS / VECTOR','矢量突破','分别抽取对手源石技艺与实力分级，完成两次抽取后进入作战。')+`<div class="vector-wheel-layout">${['art','tier'].map(kind=>{const art=BY_ID[r.art],done=kind==='art'?!!art:r.enemyTier!==undefined,rolling=animation?.type==='vector'+(kind==='art'?'Art':'Tier')&&spinning,result=done?(kind==='art'?art.name+'（'+art.source+'）':tierLabel(r.enemyTier)):'',options=kind==='art'?artsOptions(false,true):vectorTierOptions(state.stats.rating.score);return `<section class="panel"><h2>${kind==='art'?'对手源石技艺转盘':'对手实力转盘'}</h2>${wheelMarkup({result,options,title:kind==='art'?'源石技艺原型':'对手评级',selected:done?(kind==='art'?r.art:String(r.enemyTier)):'',rolling,duration:spinDuration()})}<div class="wheel-caption">${btn(rolling?'正在揭晓…':done?'已完成抽取':'转动 · '+(kind==='art'?'对手源石技艺':'实力分级'),'drawVector:'+kind,'primary',spinning||done)}</div></section>`;}).join('')}</div><div class="vector-ready"><p>${r.art&&r.enemyTier!==undefined?esc(BY_ID[r.art].source)+' · '+esc(tierLabel(r.enemyTier)):'完成两个独立转盘，确认本次对手。'}</p>${btn('进入突破作战','beginVector','primary',spinning||!r.art||r.enemyTier===undefined)}<p class="smalltext muted">50%抽同级，50%抽较低级；最下位只抽同级。训练不消耗补给；结算后生命回满。18轮起力竭，120轮防僵局。</p></div>`;}

function activity(no,title,desc,action){return `<button class="activity" data-act="${action}" ${state.days<=0?'disabled':''}><span class="number">${no} / DAY ACTION</span><h3>${title}</h3><p>${desc}</p></button>`;}
function prep(){let n=Run.nodeOf(state),b=Run.battleSpec(state);return pagehead('OPERATION / '+b.id,b.title,n.name,btn('开始作战','beginBattle','primary'))+`<div class="layout"><div><section class="panel"><div class="briefing-marks">${nodeFactions(n.id).map(f=>factionImage(f)).join('')}</div><div class="eyebrow">MISSION BRIEFING</div><p style="margin:14px 0">${esc(narrative(b))}</p><h3>本场任务</h3><p>${esc(mission(b)).replace(/180路障/g,'500生命路障')}</p></section><section class="panel"><h3>${state.solo?'一人成军 · 独立行动':'我方队伍 · 队友自动行动'}</h3><div class="cards-grid"><article class="skill"><h3>${esc(state.name)}</h3><p>${esc(BY_ID[state.art].name)} · 熟练度${state.mastery}</p><small>生命 ${fmt(state.hp)}/${fmt(state.stats.H)}</small></article>${b.allies.map(id=>{let u=DATA.campaign.units.find(u=>u.id===id);return `<article class="skill"><h3>${esc(u.name)}</h3><p>${tierLabel(numericRating(u.stats).score)}</p><small>生命 ${fmt(state.allyHP?.[id]?.hp??u.stats.H)}/${fmt(u.stats.H)}</small></article>`;}).join('')}</div>${masteryConfig()}</section><section class="panel"><h3>敌方阵列</h3>${b.enemies.map(id=>{let u=DATA.campaign.units.find(u=>u.id===id);return `<div class="journal"><h3>${esc(u.name)}</h3><small>${tierLabel(numericRating(u.stats).score)} · 生命 ${fmt(u.stats.H)} · 体术 ${fmt(u.stats.A)} · 源石技艺 ${fmt(u.stats.P)}</small></div>`;}).join('')}</section></div>${side()}</div>`;}

function unitUI(b,u){const intent=u.intent,sk=intent&&Battle.skill(u,intent.button);return `<button class="unit compact-unit ${u.isPlayer?'player':''} ${u.side==='enemy'?'enemy':''} ${!Battle.alive(u)?'dead':''} ${b.actor===u.id?'current':''} ${target===u.id?'target':''}" data-act="target:${u.id}" aria-label="选择${esc(u.name)}"><div class="unit-title"><strong>${factionImage(unitFaction(u,u.cardData?.source||BY_ID[u.card]?.source))||roleIcon(u)}${esc(u.name)}${u.isPlayer?hiddenMark(Battle.cardOf(u)):''}</strong><small title="${esc(u.facility?'设施':tierLabel(numericRating(u.stats).score))}">${u.facility?'设施':tierLabel(numericRating(u.stats).score).split(' · ').map((text,i)=>`<span class="${i?'tier-description':'tier-code'}">${esc(text)}</span>`).join('')}</small></div>${u.owner?'<span class="summon-label">召唤物 · '+esc(u.summonRole||'支援')+'</span>':''}<div class="unit-hp"><span>生命 ${fmt(u.hp)}/${fmt(u.stats.H)}</span>${Battle.shields(u)?'<span>盾'+fmt(Battle.shields(u))+'</span>':''}</div>${bar(u.hp,u.stats.H,'hp')}<div class="unit-hp"><span>技力 ${fmt(u.e)}/${u.stats.Emax}</span><span>行动 ${fmt(u.gauge)}</span></div>${u.stats.Emax?`<div class="bar energy" role="meter" aria-label="${esc(u.name)}的技力" aria-valuenow="${Math.floor(u.e)}" aria-valuemin="0" aria-valuemax="${u.stats.Emax}"><i style="width:${clamp(u.e/u.stats.Emax*100,0,100)}%"></i></div>`:''}${resourceMeterUI(b,u)}<div class="statusrow">${!Battle.alive(u)?'<span>已退场</span>':''}${Object.keys(u.statuses).filter(n=>Battle.has(u,n)).map(n=>`<span title="${esc(STATUS_INFO[n]||n)}">${esc(n)}${Battle.stacks(u,n)>1?'×'+Battle.stacks(u,n):''}</span>`).join('')}${isLeader(u)?'<span class="leader-tag">'+'敌方领袖'+'</span>':''}${u.defending?'<span>防御</span>':''}${u.revives?'<span>复起'+u.revives+'</span>':''}</div>${u.side==='enemy'&&Battle.active(u)?`<small class="intent">${esc(sk?.name||{martial:'体术',rest:'休整',defend:'防御'}[intent?.button]||'待机')} → ${esc(b.units.find(v=>v.id===intent?.target)?.name||'—')}</small>`:''}</button>`;}
function cooperative(a){const scan=ops=>(ops||[]).some(o=>o.to==='ally'||scan(o.effects)||scan(o.otherwise));return !!a&&(a.target?.startsWith('ally')||scan(a.ops));}
function chooseTarget(b,u,a){let ts=Battle.targets(b,u,a||{target:'enemy_one',ops:[]});const chosen=ts.find(v=>v.id===target);if(chosen)return chosen;return ts.sort((x,y)=>a?.target?.startsWith('ally')&&a.ops.some(o=>o.op==='energy')?x.e/Math.max(1,x.stats.Emax)-y.e/Math.max(1,y.stats.Emax):x.hp/x.stats.H-y.hp/y.stats.H)[0]||u;}

function battleView(){let b=state.battle,u=b.units.find(v=>v.id===b.actor),p=b.units.find(v=>v.isPlayer),controlled=u?.isPlayer&&Battle.active(u)&&!b.over,inspected=b.units.find(v=>v.id===detailUnit)||p;let a=Battle.skill(p,selection),benefit=['A','B','C'].some(k=>cooperative(Battle.skill(p,k)));return `<section class="combat-screen"><section class="mission-strip"><div><div class="eyebrow">OPERATION / ${esc(b.spec.id)}${b.config.hazard?' · 险路恶敌':''}</div><h2>${esc(b.spec.title)}</h2><p>${esc(narrative(b.spec))}</p><strong class="mission-goal">任务：${esc(mission(b.spec)).replace(/180路障/g,'500生命路障')}</strong><small>${sceneSummary(b).map(esc).join(' · ')}</small></div><div class="battle-tools">${btn('任务','battleBrief','mobile-only small')}${btn(pause?'继续':'暂停','pause','small')}${btn(auto?'停止托管':'托管','auto','small')}${state.mode==='sandbox'?btn('退出','leaveSimulation','small'):btn('撤离','forfeit','small')}</div></section><div class="combat-center"><div class="arena"><section class="array"><div class="array-heading">敌方阵列 <small>第${b.round}轮 · ${b.units.filter(v=>v.side==='enemy'&&!v.removed&&Battle.alive(v)).length}单位</small></div><div class="unit-list">${b.units.filter(v=>v.side==='enemy'&&!v.removed).map(v=>unitUI(b,v)).join('')}</div></section><section class="array"><div class="array-heading">我方阵列 <small>${b.units.filter(v=>v.side==='ally'&&!v.removed&&Battle.alive(v)).length}单位 · ${state.solo?'一人成军 · 召唤物自动':'队友自动'}</small></div><div class="unit-list">${b.units.filter(v=>v.side==='ally'&&!v.removed).map(v=>unitUI(b,v)).join('')}</div></section></div><aside class="info-panels" data-mobile-panel="${mobilePanel}" data-mobile-skill="${mobileSkill}"><nav class="mobile-info-tabs mobile-only" aria-label="战斗信息">${[['skills','技能'],['file','档案'],['log','记录']].map(([key,label])=>btn(label,'mobilePanel:'+key,mobilePanel===key?'selected':'',false,`aria-pressed="${mobilePanel===key}"`)).join('')}</nav><section class="skills-pane"><h3>源石技艺 · ${esc(BY_ID[state.art].name)} ${hiddenMark(BY_ID[state.art])}</h3>${liveResourceUI(b,p)}<nav class="mobile-skill-tabs mobile-only" aria-label="查看技能说明">${['A','B','C'].map(k=>btn(k+' · '+(Battle.skill(p,k)?Battle.cost(p,Battle.skill(p,k)):0)+' E','mobileSkill:'+k,mobileSkill===k?'selected':'',false,`aria-pressed="${mobileSkill===k}"`)).join('')}${btn('全文','battleSkillRead','skill-read',false,'aria-label="阅读完整技能说明"')}</nav><div class="skill-descriptions">${['A','B','C'].map(k=>{let a=Battle.skill(p,k),why=Battle.legal(b,p,k);return `<article data-skill="${k}" class="${selection===k?'highlight':''}"><strong>${k} · ${esc(a?.label||a?.name||'未配置')}</strong><small>${a?Battle.cost(p,a):0} E · ${targetLabel(a?.target)}${a?.cd?' · 冷却'+a.cd+'回合':''}${why?' · '+esc(why):''}</small><p>${esc(a?chineseText(actionText(a)):'暂无招式')}</p></article>`;}).join('')}<p class="smalltext">体术：100%体术强度物伤。休整：恢复8%生命、${restEnergy(p.stats.Emax)}技力；每次自身行动自然恢复${energyRegen(p.stats.Emax)}技力；防御：12%生命护盾与40%直接减伤，至下次自身行动。</p></div></section><section class="battle-file" data-inspecting="${inspected.id===p.id?'player':'other'}"><div class="paper-stamp" aria-hidden="true">${factionImage(FACTIONS.rhodes)}</div><h3>博士档案 ${hiddenMark(BY_ID[state.art])} ${btn('详情','archive','ghost small')}</h3><strong>${esc(tierLabel(state.stats.rating.score))}</strong><p><span class="mobile-file-grade mobile-only">综合 ${esc(tierLabel(state.stats.rating.score).split(' · ')[0])} · </span>天赋 ${esc(state.talent)} ×${state.multiplier} · 熟练度 ${state.mastery}/200</p><div class="file-values">${[['H','生命上限'],['A','体术强度'],['P','源石技艺强度'],['D','防御'],['R','魔抗'],['Emax','技力上限']].map(([k,l])=>`<span><span class="stat-label">${l.replace(/上限|强度/g,'')}</span><b>${fmt(p.stats[k])}</b><small class="stat-tier" title="${esc(statTier(p.stats,k))}">${esc(statTier(p.stats,k).split(' · ')[0])}</small></span>`).join('')}</div>${resourceMeterUI(b,p)}<p class="inspect-line">${inspected.id!==p.id?esc(inspected.name)+' · '+tierLabel(numericRating(inspected.stats).score)+' · 防御 '+fmt(inspected.stats.D)+' / 魔抗 '+fmt(inspected.stats.R)+' / 体术 '+fmt(inspected.stats.A)+' / 源石技艺 '+fmt(inspected.stats.P):esc(BY_ID[state.art].source)}</p></section><section class="log-pane"><h3>作战记录</h3><div class="battle-log" id="battle-log">${b.log.slice(-60).map(l=>`<p class="${l.kind}"><span>${l.seq.toString().padStart(3,'0')}</span> ${esc(l.text)}</p>`).join('')}</div></section></aside></div><section class="command-pane"><div class="command-heading"><strong>${b.over?(b.over.won?'作战成功 · 即将结算成长':'作战结束'):!Battle.alive(p)?'博士已退场 · 观战中，友方自动作战':controlled?'博士的行动 · 点击按钮立即执行':(u?esc(u.name)+'正在行动':'行动序列推进中')}</strong><span>${target?'目标 '+esc(b.units.find(v=>v.id===target)?.name||'—'):'未选目标时自动选择'}</span></div><div class="battle-subtitles" aria-label="技能彩蛋字幕区"><span>PRTS / 作战通讯</span></div>${battleBranches(b,p)}<div class="action-buttons">${['martial','A','B','C','rest','defend'].map(k=>{let a=Battle.skill(p,k),why=Battle.legal(b,p,k);return btn(({martial:'体术',rest:'休整',defend:'防御'}[k]||`<b class="action-seal">${k}</b><span class="action-name">${esc(a?.label||a?.name||'源石技艺')}</span>`)+`<small>${a?Battle.cost(p,a)+' E':'0 E'}</small>`,'cast:'+k,selection===k?'selected':'',!controlled||!!why||pause,`title="${esc(why||'立即执行')}"`);}).join('')}</div><details class="aux-menu" ${auxOpen||!compactCombat.matches?'open':''}><summary>补给与协同 <span>补给 ${b.supply}</span></summary><div class="aux-controls">${btn('急救 · 2补给（现有'+b.supply+'）','cast:firstAid','small',!controlled||!!Battle.legal(b,p,'firstAid')||pause)}${btn('野战护理 · 4补给（现有'+b.supply+'）','cast:fieldMedical','small',!controlled||!!Battle.legal(b,p,'fieldMedical')||pause)}${benefit?`<label>协同受益者<select id="ally-target"><option value="">自动 · 最需要增益</option>${Battle.allies(b,p).filter(v=>!v.facility&&(p.card!=='AK011'||!v.owner)).map(v=>`<option value="${v.id}" ${beneficiary===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label>`:''}${p.card==='AK001'?'<label>押注<select id="wager"><option value="attack">攻击</option><option value="support">非攻击</option></select></label>':''}${b.spec.id==='N11-3'?'<label><input id="charge" type="checkbox">主炮充能</label>':''}<label><input id="cover" type="checkbox">防御掩护</label></div></details></section></section>`;}

function result(){if(state.mode==='sandbox')return pagehead('PRTS / SIMULATION','模拟结束',esc(state.lastResult.reason))+`<section class="panel"><p>本次模拟不改变旅程档案。</p><div class="toolbar">${btn('再试一次','nextBattle','primary')}${btn('更换模拟配置','simulation')}${btn('返回旅程','leaveSimulation')}</div></section>`;let r=state.lastResult;return pagehead('DEBRIEF / '+r.id,r.won?'作战成功':'撤离评估',esc(r.title))+`<div class="layout"><section class="panel"><div class="result-banner"><div class="eyebrow">${r.won?'OBJECTIVE RESOLVED':'ACTION ENDED'}</div><h2>${esc(r.reason)}</h2><p class="muted">${r.kind==='objective'?'任务已完成；Boss战果按实际退场情况记录。':r.won?'敌方威胁已解除。':'本次成长保留，失败不会被记作通关。'}</p></div><div class="result-cells"><div><strong>+${r.mastery}</strong><small>源石技艺熟练度</small></div><div><strong>${r.rounds}</strong><small>场景轮</small></div><div><strong>${state.supply}</strong><small>当前补给</small></div></div>${state.mastery>=100?`<div class="notice">${state.mastery>=200?'升变与异格增益已自动应用。':'A/B专精已自动应用。'}</div>${masteryConfig()}`:''}<div class="toolbar">${r.won?btn(state.battleIndex===3?'结算本节点':'下一场作战','nextBattle','primary'):btn('查看旅程结局','evacuate','primary')}</div>${r.alreadyClaimed?'<p class="smalltext muted">本遭遇奖励已经结算，未重复发放。</p>':''}</section>${side()}</div>`;}
function nodeEnd(){return pagehead('CHAPTER / COMPLETE',Run.nodeOf(state).name,state.nodeSuccess?'本节点行动完成。':'本节点记录为未完成撤离。')+`<section class="panel result-banner"><h2>${state.nodeSuccess?'留下你的足迹':'活着，走向下一段旅程'}</h2><p class="muted" style="margin:18px 0">${state.mode==='campaign'&&state.nodeIndex<11?'下一节点：'+esc(DATA.campaign.nodes[state.nodeIndex+1].name)+' · 转场准备 '+Run.TRANSITION[state.nodeIndex]+'日':'本次旅程将生成结局档案。'}</p>${btn(state.mode==='campaign'&&state.nodeIndex<11?'继续旅程':'查看结局','nextNode','primary')}</section>`;}
function ending(){return endingMarkup(state);}

function route(){return pagehead('WORLD / CHRONICLE','穿越时间线','从起点向前推进。每个节点包含四场作战，开局准备日只领取一次。',btn('返回游戏','back','small'))+`<section class="route">${DATA.campaign.nodes.map((n,i)=>`<article class="route-card ${state&&i===state.nodeIndex?'current':''} ${state&&i<state.nodeIndex?'past':''}"><div class="node-insignia">${nodeFactions(n.id).map(f=>factionImage(f)).join('')}</div><div class="eyebrow">${n.id} / CH.${n.chapters}</div><h3>${esc(n.name)}</h3><small>独立开局 ${[20,18,18,16,16,14,30,24,22,20,18,16][i]}日 · 4场作战</small><p class="smalltext muted">推荐 ${TIERS[n.recommended_score[0]]}起</p><div style="margin-top:12px">${btn('查看任务','node:'+n.id,'small')}</div></article>`).join('')}</section>`;}
function codex(){let cards=CARDS.filter(c=>(pool==='all'||c.pool===pool)&&(!search||(c.source+c.name).includes(search)));return pagehead('ARCHIVE / ORIGINIUM ARTS','源石技艺图鉴','查阅招式、消耗与召唤规则。隐藏源石技艺仍需熟练度200才能升变。',btn('返回游戏','back','small'))+`<div class="formgrid"><label>搜索干员或源石技艺<input id="search" value="${esc(search)}" placeholder="例如：霜叶、奇美拉、冬痕"></label><label>源石技艺池<select id="pool"><option value="all">全部 · ${CARDS.length}项</option><option value="normal" ${pool==='normal'?'selected':''}>普通池 · ${CARDS.filter(c=>c.pool==='normal').length}项</option><option value="hidden" ${pool==='hidden'?'selected':''}>隐藏池 · ${CARDS.filter(c=>c.pool==='hidden').length}项</option></select></label></div><p class="smalltext muted" style="margin-bottom:18px">${cards.length}项结果</p>${!cards.length?'<div class="notice">没有匹配的源石技艺，请修改搜索名称或切换技艺池。</div>':''}<div class="codex-list">${cards.map(c=>`<button class="codex-card" data-act="card:${c.id}"><div class="row">${tag(c.pool==='hidden'?'隐藏':'普通',c.pool==='hidden'?'gold':'')}<small class="muted">${esc(c.source)}</small></div>${factionImage(sourceFaction(c.source),'codex-insignia')}<h3 style="margin-top:10px">${roleIcon({card:c.id,stats:{A:1,P:1}})}${esc(c.name)}</h3><p>${esc(artResourceRule(c)?'专属资源：'+artResourceRule(c).name+' · 上限'+artResourceRule(c).cap:c.marker?'专属标记：'+c.marker:c.ascend?'升变：'+c.ascend:'查看完整招式')}</p></button>`).join('')}</div>`;}
function openModal(title,html){const wasPaused=pause,previousBattle=state?.battle;pause=true;modal.innerHTML=`<div class="modal-head"><div><div class="eyebrow">FIELD MANUAL</div><h2>${esc(title)}</h2></div><button data-close aria-label="关闭">×</button></div>${html}`;modal.showModal();modal.querySelectorAll('[data-act]').forEach(el=>el.onclick=()=>{const action=el.dataset.act;modal.close();handle(action);});modal.querySelector('[data-close]').onclick=()=>modal.close();modal.onclose=()=>{pause=wasPaused&&state?.battle===previousBattle;if(view==='play'&&state?.phase==='battle')render();};}
function showCard(id){let c=BY_ID[id];openModal(c.name,`<p class="prototype-affiliation">${factionImage(sourceFaction(c.source))}${esc(c.source)} · ${c.pool==='hidden'?'隐藏池':'普通池'}${c.ascend?' · M200 '+esc(c.ascend):''}</p><div class="notice">${artResourceRule(c)?'专属资源：'+esc(artResourceRule(c).name)+'，初始'+c.initial+'，上限'+artResourceRule(c).cap+'。 ':''}${esc(c.tip||'根据敌方意图调整招式顺序。')}</div>${c.passiveText?.length?`<section class="journal"><h3>初始特性</h3>${c.passiveText.map(t=>`<p class="smalltext">${esc(t)}</p>`).join('')}</section>`:''}<h3 style="margin:20px 0 12px">基础招式 · M0</h3>${skillPanels(c,0,true)}<h3 style="margin:20px 0 12px">升变配置 · M200</h3>${skillPanels(c,200)}<p style="margin-top:18px" class="smalltext muted">每次自身机会自然恢复 max(12,6%技力上限)技力；基础费用按操控20折算为90%并向上取整。冷却N表示用后封锁接下来N次机会。</p><p class="smalltext" style="margin-top:12px"><a href="${esc(c.url)}" target="_blank" rel="noreferrer">查看角色原型资料</a></p>`);}
function showHelp(){openModal('规则',rulesMarkup(DATA));}
function schedule(){if(leaderBusy()){timer=setTimeout(schedule,100);return;}if(pause||spinning||modal.open)return;let b=state.battle;if(b.over){timer=setTimeout(()=>{try{const r=Run.settle(state);toast((r.won?'作战成功':'行动结束')+' · 熟练度 +'+r.mastery);auto=false;persist();render();}catch(e){pause=true;toast(e.message);}},900);return;}let u=b.units.find(v=>v.id===b.actor);if(!u||!Battle.active(u)){timer=setTimeout(()=>{try{Battle.advance(b);persist();render();}catch(e){toast(e.message);pause=true;}},100);return;}if(!u.isPlayer||auto){timer=setTimeout(()=>{try{let intent=Battle.chooseAI(b,u);Battle.act(b,intent.button,intent.target,intent.choice||{});persist();render();}catch(e){auto=false;pause=true;toast(e.message);render();}},auto?70:400);}}
function animate(type,step,after){const duration=spinDuration();spinning=true;animation={type,step,duration};render();setTimeout(()=>{spinning=false;animation=null;after?.();persist();render();},duration);}

function config(){if(!state)return;let spec=document.querySelector('#spec'),extreme=document.querySelector('#extreme'),mode=document.querySelector('#summon-mode');if(spec&&!spec.disabled)state.specialization=spec.value;if(extreme&&!extreme.disabled)state.extreme=!!extreme.value;if(mode)state.summonMode=Number(mode.value);persist();}
async function handle(action){try{if(action==='feedback'){feedbackReturn=view==='feedback'?feedbackReturn:view;view='feedback';history.replaceState(null,'','#feedback');render();window.scrollTo({top:0,behavior:'instant'});return;}if(action==='feedbackBack'){view=feedbackReturn;history.replaceState(null,'',location.pathname+location.search);render();return;}if(action==='endingThanks'){openModal('旅程之后 · 致谢',thanksMarkup());return;}if(action==='closeThanks'||action==='copyFeedback')return;if(action.startsWith('mobilePanel:')){mobilePanel=action.split(':')[1];syncMobilePanels();return;}if(action.startsWith('mobileSkill:')){mobileSkill=action.split(':')[1];mobilePanel='skills';syncMobilePanels();app.querySelector('.skills-pane')?.scrollTo(0,0);return;}if(action==='battleSkillRead'){const b=state.battle,p=b.units.find(u=>u.isPlayer),a=Battle.skill(p,mobileSkill);openModal(mobileSkill+' · '+(a?.label||a?.name||'源石技艺'),`<p class="skill-meta">${a?Battle.cost(p,a):0} 技力 · ${targetLabel(a?.target)}${a?.cd?' · 冷却'+a.cd+'回合':''}</p><p class="full-skill-text">${esc(a?chineseText(actionText(a)):'暂无招式')}</p>`);return;}if(action==='battleBrief'){const b=state.battle;openModal(b.spec.title,`<p>${esc(narrative(b.spec))}</p><div class="notice"><strong>本场任务</strong><p>${esc(mission(b.spec)).replace(/180路障/g,'500生命路障')}</p></div><p>${sceneSummary(b).map(esc).join(' · ')}</p>`);return;}if(action==='toggleMemes'){toast(toggleMemes()?'技能彩蛋已开启':'技能彩蛋已关闭');render();return;}if(action.startsWith('wheelSpeed:')){if(spinning)return;localStorage.setItem('terra-wheel-speed',String(normalizeSpeed(action.split(':')[1])));render();return;}if(action==='wheelMotion'){localStorage.setItem('terra-ui-motion',motionReduced()?'full':'reduced');render();return;}if(action==='simulation'){openModal('PRTS模拟作战',`<p class="muted">自由试用源石技艺和升变，对战剧情单位；保留你的正式旅程。</p><div class="formgrid"><label>源石技艺<select id="sim-art">${CARDS.map(c=>`<option value="${c.id}">${esc(c.source)} · ${esc(c.name)}${c.pool==='hidden'?'〔隐藏〕':''}</option>`).join('')}</select></label><label>五项战力<select id="sim-tier">${TIERS.map((n,i)=>`<option value="${i}" ${i===3?'selected':''}>${tierLabel(i)}</option>`).join('')}</select></label><label>熟练度<select id="sim-mastery"><option value="0">M0 · 基础</option><option value="100">M100 · 专精</option><option value="200" selected>M200 · 升变</option></select></label><label>敌方原型<select id="sim-enemy">${DATA.campaign.units.map(u=>`<option value="${u.id}">${esc(u.name)} · ${esc(tierLabel(numericRating(u.stats).score))}</option>`).join('')}</select></label></div><p class="smalltext muted">敌方采用剧情面板，双方评级不产生伤害修正；电弧仆役类型可在战前配置。</p>${btn('开始模拟','startSimulation','primary')}`);modal.querySelector('[data-act=startSimulation]').onclick=()=>handle('startSimulation');return;}if(action==='startSimulation'){state=Run.createSandbox({art:document.querySelector('#sim-art').value,tier:Number(document.querySelector('#sim-tier').value),mastery:Number(document.querySelector('#sim-mastery').value),enemy:document.querySelector('#sim-enemy').value});view='play';auto=false;pause=false;modal.close();render();return;}if(action==='leaveSimulation'){state=Run.load();view=state?'play':'home';auto=false;pause=false;render();return;}if(action.startsWith('card:')){showCard(action.slice(5));return;}if(action.startsWith('node:')){let n=DATA.campaign.nodes.find(n=>n.id===action.slice(5));openModal(n.name,n.battles.map(b=>`<section class="panel"><h3>${b.id} ${esc(b.title)}</h3><p>${esc(mission(b))}</p><p class="smalltext muted">${esc(narrative(b))}</p></section>`).join(''));return;}
 if(action==='new'){let options={name:document.querySelector('#name').value.trim()||'穿越者',seed:document.querySelector('#seed').value||freshSeed(),mode:document.querySelector('#mode').value,iron:document.querySelector('#iron').checked,legend:document.querySelector('#legend').checked,solo:document.querySelector('#solo').checked,hazard:document.querySelector('#hazard').checked,node:document.querySelector('#start-node').value};if(state){openModal('新建旅程',`<p>当前档案将由新旅程替换。可先导出备份。</p><div class="toolbar">${btn('导出当前存档','export')}${btn('确认新建','confirmNew','primary')}</div>`);modal.querySelector('[data-act=export]').onclick=()=>handle('export');modal.querySelector('[data-act=confirmNew]').onclick=()=>{state=Run.createRun(options);view='play';modal.close();persist();render();};return;}state=Run.createRun(options);view='play';}
 else if(action==='continue'||action==='back'){view=state?'play':'home';}
 else if(action==='home'){view='home';}
 else if(action==='codex'){view='codex';}
 else if(action==='route'){view='route';}
 else if(action==='help'){showHelp();return;}
 else if(action==='statuses'){openModal('状态与数值说明',Object.entries(STATUS_INFO).map(([k,v])=>`<div class="journal"><h3>${k}</h3><p class="smalltext muted">${v}</p></div>`).join(''));return;}
 else if(action==='roll'){if(spinning)return;const step=state.step;Run.drawNext(state);finalReveal=state.step===11;persist();animate('creation',step);return;}
 else if(action==='revealArchive'){finalReveal=false;}
 else if(action==='daily'){if(spinning)return;vectorPreview='tier';Run.train(state);persist();animate('daily',null,()=>{persist();render();});return;}
 else if(action==='continueTrainingGrowth'){delete state.pendingTrainingGrowth;}
 else if(action.startsWith('vectorWheel:')){if(spinning)return;vectorPreview=action.slice(12);}
 else if(action.startsWith('drawVector:')){if(spinning)return;const kind=action.slice(11);if(kind==='art')Run.drawVectorArt(state);else Run.drawVectorTier(state);persist();animate(kind==='art'?'vectorArt':'vectorTier');return;}
 else if(action==='beginVector'){Run.beginVector(state);auto=false;pause=false;}
 else if(action==='archive'){openModal('博士档案',side()+growthJournal());return;}
 else if(action==='skipSpin'){spinning=false;}
 else if(action==='confirm'){Run.enterNode(state,true);}
 else if(action==='reserve'){Run.reserveDay(state);}
 else if(action==='depart'){config();Run.depart(state);}
 else if(action==='intel'){Run.buyIntel(state);}
 else if(action==='fieldMedical'){throw Error('请在博士行动时使用补给');}
 else if(action==='firstAid'){throw Error('请在博士行动时使用补给');}
 else if(action==='beginBattle'){config();Run.beginBattle(state);selection='martial';mobilePanel='skills';mobileSkill='A';auxOpen=false;target=null;auto=false;pause=false;}
 else if(action.startsWith('target:')){target=action.slice(7);detailUnit=target;}
 else if(action.startsWith('intent:')){selection=action.slice(7);}
 else if(action.startsWith('cast:')){if(pause||spinning)return;const b=state.battle,u=b.units.find(v=>v.id===b.actor);if(!u?.isPlayer||!Battle.active(u))return;selection=action.slice(5);if(['A','B','C'].includes(selection))mobileSkill=selection;const a=Battle.skill(u,selection),t=chooseTarget(b,u,a);const choices={ally:document.querySelector('#ally-target')?.value||beneficiary||undefined,wager:document.querySelector('#wager')?.value,mode:document.querySelector('#action-mode')?.value,charge:!!document.querySelector('#charge')?.checked,cover:!!document.querySelector('#cover')?.checked};auxOpen=false;Battle.act(b,selection,t.id,choices);branchChoice=null;}
 else if(action==='execute'){let choices={ally:document.querySelector('#ally-target')?.value,wager:document.querySelector('#wager')?.value,mode:document.querySelector('#action-mode')?.value,charge:!!document.querySelector('#charge')?.checked,cover:!!document.querySelector('#cover')?.checked};Battle.act(state.battle,selection,target,choices);}
 else if(action==='pause'){pause=!pause;}
 else if(action==='auto'){auto=!auto;pause=false;}
 else if(action==='forfeit'){openModal('终止本场',`<p>确认终止将按剧情作战失败结算，并立即结束本局。</p><div class="toolbar">${btn('继续作战','cancelForfeit','primary')}${btn('确认终止','confirmForfeit','danger')}</div>`);modal.querySelector('[data-act=cancelForfeit]').onclick=()=>modal.close();modal.querySelector('[data-act=confirmForfeit]').onclick=()=>{state.battle.over={won:false,kind:'defeat',reason:'主动终止本次作战'};modal.close();persist();render();};return;}
 else if(action==='settle'){Run.settle(state);auto=false;}
 else if(action==='continueGrowth'){Run.continueGrowth(state);selection='martial';target=null;auto=false;pause=false;}
 else if(action==='nextBattle'){config();Run.nextBattle(state);}
 else if(action==='retry'){Run.retry(state);}
 else if(action==='evacuate'){Run.evacuate(state);}
 else if(action==='nextNode'){Run.nextNode(state);}
 else if(action==='saveMenu'){openModal('档案管理',`<p>当前进度已自动保存。导出文件可用于备份或跨设备继续。</p><div class="toolbar">${btn('导出存档','export','primary')}${btn('导入存档','import')}${btn('返回标题','home')}</div>`);modal.querySelectorAll('[data-act]').forEach(el=>el.onclick=()=>{let a=el.dataset.act;modal.close();handle(a);});return;}
 else if(action==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='泰拉档案-'+state.seed.replace(/[^a-zA-Z0-9_-]/g,'_')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 else if(action==='import'){const input=document.createElement('input');input.type='file';input.accept='.json';input.hidden=true;document.body.append(input);input.oncancel=()=>input.remove();input.onchange=async()=>{try{let f=input.files[0];if(!f)return;if(f.size>5e6)throw Error('存档文件过大');let s=JSON.parse(await f.text());Run.validateSave(s);Run.refreshBattleCards(s);state=s;view='play';persist();render();toast('档案已恢复');}catch(e){toast('导入失败：'+e.message);}finally{input.remove();}};input.click();return;}
 persist();render();}catch(e){console.error(e);toast(e.message);}}
function syncMobilePanels(){if(compactCombat.matches){auxOpen=false;const aux=app.querySelector('.aux-menu');if(aux)aux.open=false;}const panels=app.querySelector('.info-panels');if(!panels)return;panels.dataset.mobilePanel=mobilePanel;panels.dataset.mobileSkill=mobileSkill;for(const el of panels.querySelectorAll('[data-act^="mobilePanel:"],[data-act^="mobileSkill:"]')){const [type,key]=el.dataset.act.split(':');const selected=key===(type==='mobilePanel'?mobilePanel:mobileSkill);el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected));}}
function bind(){bindWheels(app);bindFeedback(app,toast);if(compactCombat.matches)app.querySelector('.aux-menu')?.addEventListener('toggle',e=>{if(e.currentTarget.isConnected)auxOpen=e.currentTarget.open;});const navAction=view==='codex'?'codex':view==='route'?'route':null;app.querySelector(`[data-act="${navAction}"]`)?.classList.add('nav-active');app.querySelectorAll('[data-act]').forEach(el=>el.addEventListener('click',()=>handle(el.dataset.act)));for(let id of ['spec','extreme','summon-mode'])document.getElementById(id)?.addEventListener('change',config);document.querySelector('#pool')?.addEventListener('change',e=>{pool=e.target.value;render();});let input=document.querySelector('#search');input?.addEventListener('input',e=>{let p=e.target.selectionStart;search=e.target.value;render();let el=document.querySelector('#search');el.focus();el.setSelectionRange(p,p);});let log=document.querySelector('#battle-log');if(log)log.scrollTop=log.scrollHeight;document.querySelector('#ally-target')?.addEventListener('change',e=>beneficiary=e.target.value);document.querySelector('#action-mode')?.addEventListener('change',e=>{const b=state?.battle,p=b?.units.find(u=>u.isPlayer);if(p)branchChoice={battle:b,unit:p.id,mode:Number(e.target.value)};});}
window.addEventListener('beforeunload',persist);

const STAT_FIELDS=[['H','生命上限'],['D','防御'],['A','体术强度'],['P','源石技艺强度'],['R','魔抗'],['Emax','技力上限']];
function precise(v){return Number.isFinite(v)?v.toLocaleString('zh-CN',{maximumFractionDigits:2}):'—';}
function growthScreen(){const r=state.pendingGrowth,b=r.before,a=r.after,changed=b.rating!==a.rating;
return `<section class="growth-screen"><div class="growth-hero"><div><div class="eyebrow">PRTS / COMBAT GROWTH</div><h1>${r.vector?'矢量突破成功':'作战成功'}</h1><p>${esc(r.title)}</p></div><div class="growth-total"><span>本场熟练度</span><strong>+${r.mastery}</strong></div></div><section class="growth-rating"><span>综合评级</span><strong>${esc(b.rating)}</strong><i>→</i><strong class="${changed?'promoted':''}">${esc(a.rating)}</strong>${changed?'<b class="growth-unlock">分级提升</b>':''}</section><div class="growth-grid">${STAT_FIELDS.map(([k,l])=>{const delta=a.stats[k]-b.stats[k],max=Math.max(1,a.stats[k]*1.13);return `<article class="growth-stat"><span>${l}</span><strong><span data-growth-from="${b.stats[k]}" data-growth-to="${a.stats[k]}">${precise(b.stats[k])}</span><b>+${precise(delta)}</b></strong><div class="growth-track"><i style="width:${b.stats[k]/max*100}%"></i><em style="--growth-before:${b.stats[k]/max*100}%;--growth-after:${a.stats[k]/max*100}%"></em></div><small>${precise(b.stats[k])}<span>→</span>${precise(a.stats[k])}</small></article>`;}).join('')}</div><section class="growth-mastery"><div><strong>源石技艺熟练度</strong><span>${b.mastery} → ${a.mastery} / 200</span></div>${bar(a.mastery,200,'gold')}<div class="growth-milestones">${[100,200].map(m=>`<span class="${a.mastery>=m?'reached':''}">${m} · ${m===100?'专精':'升变'}${b.mastery<m&&a.mastery>=m?' · 已自动应用':''}</span>`).join('')}</div></section>${[100,200].filter(m=>b.mastery<m&&a.mastery>=m).map(m=>`<div class="growth-unlock">${m===100?'专精已解锁：A/B伤害提升、技力消耗降低。':'升变已解锁：C招式与异格增益自动生效。'}</div>`).join('')}${r.record?.bosses?.length?`<div class="combat-boss-receipt"><strong>本场领袖战果已归档</strong>${r.record.bosses.map(b=>`<span>${esc(b.name)} · ${esc(OUTCOME_NAMES[b.outcome])}</span>`).join('')}</div>`:''}<div class="growth-actions"><p>${r.rescued?'博士由队伍战后救援，恢复30%最大生命。':''}本场成长已保存${r.vector?'，继续安排准备日。':'，确认后直接进入下一段行动。'}</p>${btn(r.vector?'确认成长 · 返回准备':'确认成长 · 继续行动','continueGrowth','primary')}</div><details class="growth-formula"><summary>查看成长计算</summary><p>${growthText({...r,mastery:0})}</p></details></section>`;}
function animateGrowth(){const fields=[...document.querySelectorAll('[data-growth-to]')];if(!fields.length)return;const reduced=motionReduced(),start=performance.now();function frame(t){const f=reduced?1:clamp((t-start)/800,0,1),e=1-(1-f)**3;for(const el of fields)el.textContent=precise(Number(el.dataset.growthFrom)+(Number(el.dataset.growthTo)-Number(el.dataset.growthFrom))*e);if(f<1&&fields[0].isConnected)requestAnimationFrame(frame);}requestAnimationFrame(frame);}

initMusic();
render();
function resourceRuleUI(card,mastery){const r=artResourceRule(card,mastery);return r?`<p class="resource-rule">专属资源【${esc(r.name)}】 · 上限 ${r.cap}${r.facilities?'座':'层'}</p>`:'';}
function liveResourceUI(b,u){return `<div class="live-resources" aria-live="polite">${unitResources(u,b.units).map(r=>`<div><span>${esc(r.name)}</span><strong>${r.current}<small> / ${r.cap}</small></strong><em>上限${r.cap}</em></div>`).join('')}</div>`;}
function trainingGrowthScreen(){const r=state.pendingTrainingGrowth,b=r.before,a=r.after,rows=STAT_FIELDS.filter(([k])=>a.stats[k]!==b.stats[k]);
 return `<section class="growth-screen training-growth"><div class="growth-hero"><div><div class="eyebrow">PRTS / DAILY TRAINING</div><h1>第${r.day}日 · ${esc(r.name)}完成</h1><p>${esc(r.quality)} · 训练倍率 ×${fmt(r.mult)}</p></div><div class="training-seal">${factionImage(FACTIONS.rhodes)}<span>RHODES ISLAND<br>训练记录</span></div></div><div class="training-summary">${rows.length?'本日能力提升':'本日后勤成果'}<span>生命已回满 ${precise(state.hp)} / ${precise(state.stats.H)}</span></div><div class="growth-grid">${rows.map(([k,l])=>{const delta=a.stats[k]-b.stats[k],max=Math.max(1,a.stats[k]*1.13);return `<article class="growth-stat"><span>${l}</span><strong><span data-growth-from="${b.stats[k]}" data-growth-to="${a.stats[k]}">${precise(b.stats[k])}</span><b>+${precise(delta)}</b></strong><div class="growth-track"><i style="width:${b.stats[k]/max*100}%"></i><em style="--growth-before:${b.stats[k]/max*100}%;--growth-after:${a.stats[k]/max*100}%"></em></div><small>${precise(b.stats[k])} → ${precise(a.stats[k])}</small><p class="stat-tier">${esc(statTier(b.stats,k))}<br>→ ${esc(statTier(a.stats,k))}</p></article>`;}).join('')}${r.mastery?`<article class="growth-stat"><span>源石技艺熟练度</span><strong><span data-growth-from="${b.mastery}" data-growth-to="${a.mastery}">${b.mastery}</span><b>+${r.mastery}</b></strong><small>${b.mastery} → ${a.mastery} / 200</small></article>`:''}${r.supply?`<article class="growth-stat"><span>作战补给</span><strong>+${r.supply}</strong><small>现有 ${state.supply}</small></article>`:''}</div>${[100,200].filter(m=>b.mastery<m&&a.mastery>=m).map(m=>`<div class="growth-unlock">${m===100?'专精':'升变'}已解锁并自动应用</div>`).join('')}<p class="training-formula">${esc((growthText(r)||'完成物资检整。').replace(/<br>/g,'；'))}${rows.length?'':' · 五项战斗数值本日无增长'}</p><div class="growth-actions">${btn(state.days?'确认成长 · 继续准备':'确认成长 · 准备完毕','continueTrainingGrowth','primary')}</div></section>`;
}

function resourceMeterUI(b,u){return unitResources(u,b.units).map(r=>`<div class="unit-resource" aria-label="${esc(r.name)} ${r.current}/${r.cap}"><span>${esc(r.name)}</span><strong>${r.current}<small> / ${r.cap}</small></strong><div class="resource-pips" aria-hidden="true">${Array.from({length:Math.min(r.cap,16)},(_,i)=>`<i class="${i<r.current?'filled':''}"></i>`).join('')}</div></div>`).join('');}

function roleIcon(u){const c=u.cardData||BY_ID[u.card],raw=DATA.arts.cards.find(r=>r.art_id===(c?.baseArt||c?.id)),n=raw?.source||u.name||'';const physical=(u.stats?.A||0)>(u.stats?.P||0);let kind=/能天使|陈|莱伊|维什戴尔|菲亚梅塔|蕾缪安|浮士德|弩手|狙击/.test(n)?'sniper':/泥岩|斥罪|瑕光|塞雷娅|号角|年|爱国者|重装/.test(n)?'defender':/安洁莉娜|铃兰|灵知|令|伺夜|电弧/.test(n)?'supporter':/德克萨斯|夜刀|琳琅|机械师|老鲤/.test(n)?'specialist':physical?'guard':'caster';return `<img class="role-emblem" src="assets/prts/${kind}.png" alt="" aria-hidden="true">`;}
